// Package repo is the room-service persistence boundary.
// SQL is generated by sqlc into internal/db; Store adapts it to this interface.
package repo

import (
	"context"
	"errors"
	"time"

	"github.com/google/uuid"
)

// ErrNotFound is returned when a row the statement expected is absent.
var ErrNotFound = errors.New("not found")

// Room is one whiteboard row.
type Room struct {
	ID        uuid.UUID
	AdminID   uuid.UUID
	Title     string
	CreatedAt time.Time
	Deleted   bool
}

// Member is one room_members row plus the profile username.
type Member struct {
	UserID   uuid.UUID
	Username string
	Role     string
	JoinedAt time.Time
}

// Invite is one room_invites row.
type Invite struct {
	ID        uuid.UUID
	RoomID    uuid.UUID
	TokenHash []byte
	ExpiresAt time.Time
	MaxUses   int32
	Uses      int32
}

// Tx is the query set used inside one transaction.
type Tx interface {
	CreateRoom(ctx context.Context, adminID uuid.UUID, title string) (Room, error)
	GetRoom(ctx context.Context, id uuid.UUID) (Room, error)
	SoftDeleteRoom(ctx context.Context, id uuid.UUID) error
	UpsertMember(ctx context.Context, roomID, userID uuid.UUID, role string) (Member, error)
	DeleteMember(ctx context.Context, roomID, userID uuid.UUID) error
	ListMembers(ctx context.Context, roomID uuid.UUID) ([]Member, error)
	GetMember(ctx context.Context, roomID, userID uuid.UUID) (Member, error)
	GetMemberRole(ctx context.Context, roomID, userID uuid.UUID) (string, error)
	TransferAdmin(ctx context.Context, roomID, newAdmin uuid.UUID) error
	CreateInvite(ctx context.Context, roomID uuid.UUID, hash []byte, expiresAt time.Time, maxUses int32) (Invite, error)
	GetInviteByHash(ctx context.Context, hash []byte) (Invite, error)
	IncrementInviteUse(ctx context.Context, id uuid.UUID) error
	InsertAudit(ctx context.Context, actor uuid.UUID, action, target string, roomID uuid.UUID, meta []byte) error
}

// Store runs statements on the pool and multi-statement work inside WithTx.
// GetMemberRole on the pool is the CheckMembership hot path: one indexed query.
type Store interface {
	Tx
	WithTx(ctx context.Context, fn func(Tx) error) error
}
